'use strict';

// MODULES //

import reinterpret from '@stdlib/strided-base-reinterpret-complex64';
import realf from '@stdlib/complex-float32-real';
import imagf from '@stdlib/complex-float32-imag';


// MAIN //

/**
* Replaces single-precision complex floating-point strided array elements equal to a provided search element with a specified scalar constant using alternative indexing semantics.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Complex64} searchElement - search element
* @param {Complex64} alpha - scalar constant
* @param {Complex64Array} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {Complex64Array} input array
*
* @example
* import Complex64Array from '@stdlib/array-complex64';
* import Complex64 from '@stdlib/complex-float32-ctor';
*
* var x = new Complex64Array( [ 1.0, 2.0, 0.0, 0.0, 3.0, 4.0, 0.0, 0.0 ] );
* var searchElement = new Complex64( 0.0, 0.0 );
* var alpha = new Complex64( 5.0, 5.0 );
*
* cfillEqual( x.length, searchElement, alpha, x, 1, 0 );
* // x => <Complex64Array>[ 1.0, 2.0, 5.0, 5.0, 3.0, 4.0, 5.0, 5.0 ]
*/
function cfillEqual( N, searchElement, alpha, x, strideX, offsetX ) {
	var view;
	var sre;
	var sim;
	var re;
	var im;
	var ix;
	var i;

	if ( N <= 0 ) {
		return x;
	}

	// Decompose the search element into its real and imaginary components:
	sre = realf( searchElement );
	sim = imagf( searchElement );

	// Decompose the constant into its real and imaginary components:
	re = realf( alpha );
	im = imagf( alpha );

	// Reinterpret the complex input array as a real-valued array of interleaved real and imaginary components:
	view = reinterpret( x, 0 );

	// Adjust the stride and offset to account for the interleaved storage:
	ix = offsetX * 2;
	strideX *= 2;

	for ( i = 0; i < N; i++ ) {
		if ( view[ ix ] === sre && view[ ix+1 ] === sim ) {
			view[ ix ] = re;
			view[ ix+1 ] = im;
		}
		ix += strideX;
	}
	return x;
}


// EXPORTS //

export default cfillEqual;
